def process(waterBodyTesting2023) -> pd.DataFrame:
    import pandas as pd
    df = waterBodyTesting2023.copy()
    out = pd.DataFrame({
        'column': df.columns,
        'dtype': [str(df[c].dtype) for c in df.columns],
        'non_null': [int(df[c].notna().sum()) for c in df.columns],
        'sample_values': [', '.join([str(x) for x in df[c].dropna().astype(str).head(3).tolist()]) for c in df.columns]
    })
    return out

